-- D02-D: executor-only credentials are not proof of a user's identity.
-- All approval RPCs now require short-lived operation-bound HMAC attestations
-- generated by the server *after* GoTrue user verification.
-- The app's HMAC secret MUST be provisioned separately, never committed here.
BEGIN;

CREATE EXTENSION IF NOT EXISTS pgcrypto WITH SCHEMA extensions;

CREATE TABLE alp_private.alp_approval_attestation_keys (
  key_id integer PRIMARY KEY CHECK (key_id = 1),
  key_bytes bytea NOT NULL CHECK (octet_length(key_bytes) = 32)
);
CREATE TABLE alp_private.alp_approval_used_nonces (
  nonce uuid PRIMARY KEY,
  used_at timestamptz NOT NULL DEFAULT clock_timestamp()
);
CREATE INDEX alp_approval_nonces_used_at
  ON alp_private.alp_approval_used_nonces(used_at);

REVOKE ALL ON TABLE alp_private.alp_approval_attestation_keys FROM PUBLIC, anon, authenticated;
REVOKE ALL ON TABLE alp_private.alp_approval_used_nonces FROM PUBLIC, anon, authenticated;
GRANT SELECT ON alp_private.alp_approval_attestation_keys TO service_role;
GRANT INSERT ON alp_private.alp_approval_used_nonces TO service_role;
-- Private tables: no direct executor grants. Owner/BYPASSRLS function only.
ALTER TABLE alp_private.alp_approval_attestation_keys ENABLE ROW LEVEL SECURITY;
ALTER TABLE alp_private.alp_approval_attestation_keys FORCE ROW LEVEL SECURITY;
ALTER TABLE alp_private.alp_approval_used_nonces ENABLE ROW LEVEL SECURITY;
ALTER TABLE alp_private.alp_approval_used_nonces FORCE ROW LEVEL SECURITY;

CREATE FUNCTION alp_private.verify_approval_attestation(
  p_operation text, p_actor uuid, p_arguments text[],
  p_issued_at bigint, p_nonce uuid, p_signature text
) RETURNS void LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO ''
AS $$
DECLARE
  secret bytea;
  signed_text text;
  computed text;
  current_epoch bigint;
BEGIN
  IF p_actor IS NULL OR p_operation IS NULL OR p_arguments IS NULL
     OR p_issued_at IS NULL OR p_nonce IS NULL OR p_signature IS NULL
     OR p_signature !~ '^[0-9a-f]{64}$'
     OR EXISTS (SELECT 1 FROM unnest(p_arguments) AS a(value) WHERE value IS NULL) THEN
    RAISE EXCEPTION 'invalid approval attestation' USING ERRCODE='42501';
  END IF;

  current_epoch := extract(epoch FROM clock_timestamp())::bigint;
  IF p_issued_at < current_epoch - 60 OR p_issued_at > current_epoch + 15 THEN
    RAISE EXCEPTION 'expired approval attestation' USING ERRCODE='42501';
  END IF;

  SELECT key_bytes INTO secret
  FROM alp_private.alp_approval_attestation_keys WHERE key_id=1;
  IF secret IS NULL THEN
    RAISE EXCEPTION 'approval attestation not configured' USING ERRCODE='42501';
  END IF;

  SELECT string_agg(octet_length(convert_to(value,'UTF8'))::text || ':' || value,
                    '|' ORDER BY ord)
    INTO signed_text
    FROM unnest(ARRAY[p_operation, p_actor::text] || p_arguments ||
                ARRAY[p_issued_at::text, p_nonce::text])
         WITH ORDINALITY AS part(value,ord);

  computed := encode(extensions.hmac(convert_to(signed_text,'UTF8'),
                                      secret,'sha256'),'hex');
  IF computed <> p_signature THEN
    RAISE EXCEPTION 'approval attestation mismatch' USING ERRCODE='42501';
  END IF;

  INSERT INTO alp_private.alp_approval_used_nonces(nonce) VALUES(p_nonce)
  ON CONFLICT DO NOTHING;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'replayed approval attestation' USING ERRCODE='42501';
  END IF;
END;
$$;

CREATE FUNCTION alp_private.consume_approval_quota_signed(
  p_actor uuid,p_issued_at bigint,p_nonce uuid,p_signature text
) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path TO ''
AS $$
BEGIN
  PERFORM alp_private.verify_approval_attestation(
    'quota',p_actor,ARRAY[]::text[],p_issued_at,p_nonce,p_signature);
  RETURN alp_private.consume_approval_quota(p_actor);
END;
$$;

CREATE FUNCTION alp_private.submit_role_request_signed(
  p_target uuid,p_role text,p_requester uuid,p_reason text,
  p_issued_at bigint,p_nonce uuid,p_signature text
) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path TO ''
AS $$
BEGIN
  PERFORM alp_private.verify_approval_attestation(
    'submit',p_requester,ARRAY[p_target::text,p_role,p_reason],
    p_issued_at,p_nonce,p_signature);
  RETURN alp_private.submit_role_request(p_target,p_role,p_requester,p_reason);
END;
$$;

CREATE FUNCTION alp_private.decide_role_request_signed(
  p_request_id uuid,p_reviewer uuid,p_approve boolean,p_reason text,
  p_issued_at bigint,p_nonce uuid,p_signature text
) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO ''
AS $$
BEGIN
  PERFORM alp_private.verify_approval_attestation(
    'decide',p_reviewer,ARRAY[p_request_id::text,p_approve::text,p_reason],
    p_issued_at,p_nonce,p_signature);
  PERFORM alp_private.decide_role_request(
    p_request_id,p_reviewer,p_approve,p_reason);
END;
$$;

CREATE FUNCTION alp_private.record_approval_security_event_signed(
  p_actor uuid,p_event text,p_issued_at bigint,p_nonce uuid,p_signature text
) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO ''
AS $$
BEGIN
  PERFORM alp_private.verify_approval_attestation(
    'event',p_actor,ARRAY[p_event],p_issued_at,p_nonce,p_signature);
  PERFORM alp_private.record_approval_security_event(p_actor,p_event);
END;
$$;

-- Functions have PUBLIC EXECUTE by default. Revoke before granting.
REVOKE ALL ON FUNCTION
  alp_private.verify_approval_attestation(text,uuid,text[],bigint,uuid,text),
  alp_private.consume_approval_quota_signed(uuid,bigint,uuid,text),
  alp_private.submit_role_request_signed(uuid,text,uuid,text,bigint,uuid,text),
  alp_private.decide_role_request_signed(uuid,uuid,boolean,text,bigint,uuid,text),
  alp_private.record_approval_security_event_signed(uuid,text,bigint,uuid,text)
FROM PUBLIC,anon,authenticated;

-- Ownership transfer to service_role requires temporary CREATE on the schema.
-- Remove that privilege before the transaction commits.
GRANT CREATE ON SCHEMA alp_private TO service_role;

ALTER FUNCTION alp_private.verify_approval_attestation(text,uuid,text[],bigint,uuid,text)
  OWNER TO service_role;
ALTER FUNCTION alp_private.consume_approval_quota_signed(uuid,bigint,uuid,text)
  OWNER TO service_role;
ALTER FUNCTION alp_private.submit_role_request_signed(uuid,text,uuid,text,bigint,uuid,text)
  OWNER TO service_role;
ALTER FUNCTION alp_private.decide_role_request_signed(uuid,uuid,boolean,text,bigint,uuid,text)
  OWNER TO service_role;
ALTER FUNCTION alp_private.record_approval_security_event_signed(uuid,text,bigint,uuid,text)
  OWNER TO service_role;

REVOKE CREATE ON SCHEMA alp_private FROM service_role;

-- Remove the original unverified entrypoints from the approval executor.
REVOKE EXECUTE ON FUNCTION
  alp_private.consume_approval_quota(uuid),
  alp_private.submit_role_request(uuid,text,uuid,text),
  alp_private.decide_role_request(uuid,uuid,boolean,text),
  alp_private.record_approval_security_event(uuid,text)
FROM alp_approval_executor;

-- Academic executor's existing audit entrypoint is NOT changed in this scope.
GRANT EXECUTE ON FUNCTION
  alp_private.consume_approval_quota_signed(uuid,bigint,uuid,text),
  alp_private.submit_role_request_signed(uuid,text,uuid,text,bigint,uuid,text),
  alp_private.decide_role_request_signed(uuid,uuid,boolean,text,bigint,uuid,text),
  alp_private.record_approval_security_event_signed(uuid,text,bigint,uuid,text)
TO alp_approval_executor;

-- This must never be directly available to the executor.
DO $guard$
BEGIN
  IF has_function_privilege('alp_approval_executor',
      'alp_private.submit_role_request(uuid,text,uuid,text)','EXECUTE')
     OR has_function_privilege('alp_approval_executor',
      'alp_private.decide_role_request(uuid,uuid,boolean,text)','EXECUTE')
     OR has_function_privilege('alp_approval_executor',
      'alp_private.verify_approval_attestation(text,uuid,text[],bigint,uuid,text)','EXECUTE')
     OR has_table_privilege('alp_approval_executor',
      'alp_private.alp_approval_attestation_keys','SELECT') THEN
    RAISE EXCEPTION 'D02-D approval executor cannot bypass attestation';
  END IF;
END;
$guard$;
COMMIT;
